1092	static void hci_disconn_complete_prio(struct bt_dev *hdev, struct net_buf *buf)
1093	{
1094		struct bt_hci_evt_disconn_complete *evt = (void *)buf->data;
1095		uint16_t handle = sys_le16_to_cpu(evt->handle);
1096		struct bt_conn *conn;
