1098		LOG_DBG("status 0x%02x %s handle %u reason 0x%02x",
1099			evt->status, bt_hci_err_to_str(evt->status), handle, evt->reason);
1100	
1101		if (evt->status) {
1102			return;
1103		}
1104	
1105		conn = bt_conn_lookup_handle(hdev, handle, BT_CONN_TYPE_ALL);
1106		if (!conn) {
1107			/* Priority disconnect complete event received before normal
1108			 * connection complete event.
1109			 */
1110			conn_handle_disconnected(hdev, handle, evt->reason);
1111			return;
1112		}
1113	
1114		conn->err = evt->reason;
1115	
1116		bt_conn_set_state(conn, BT_CONN_DISCONNECT_COMPLETE);
1117		bt_conn_unref(conn);
