 280	static ssize_t sf32lb52_bt_h4_packet_len(const uint8_t *data, size_t len)
 281	{
 282	  uint16_t payload_len;
 283	
 284	  if (len < H4_HEADER_SIZE)
 285	    {
 286	      return 0;
 287	    }
 288	
 289	  switch (data[0])
 290	    {
 291	      case H4_EVT:
 292	        if (len < H4_HEADER_SIZE + sizeof(struct bt_hci_evt_hdr_s))
 293	          {
 294	            return 0;
 295	          }
 296	
 297	        payload_len = data[H4_HEADER_SIZE + 1];
 298	        return H4_HEADER_SIZE + sizeof(struct bt_hci_evt_hdr_s) + payload_len;
 299	
 300	      case H4_ACL:
 301	        if (len < H4_HEADER_SIZE + sizeof(struct bt_hci_acl_hdr_s))
 302	          {
 303	            return 0;
 304	          }
 305	
 306	        payload_len = sf32lb52_bt_get_le16(&data[H4_HEADER_SIZE + 2]);
 307	        return H4_HEADER_SIZE + sizeof(struct bt_hci_acl_hdr_s) + payload_len;
 308	
 309	      case H4_ISO:
 310	        if (len < H4_HEADER_SIZE + sizeof(struct bt_hci_iso_hdr_s))
 311	          {
 312	            return 0;
 313	          }
 314	
 315	        payload_len = sf32lb52_bt_get_le16(&data[H4_HEADER_SIZE + 2]) & 0x3fff;
 316	        return H4_HEADER_SIZE + sizeof(struct bt_hci_iso_hdr_s) + payload_len;
 317	
 318	      default:
