 323	static void sf32lb52_bt_normalize_event(uint8_t *data, size_t len)
 324	{
 325	  uint16_t opcode;
 326	
 327	  if (len < H4_HEADER_SIZE + sizeof(struct bt_hci_evt_hdr_s) + 4 ||
 328	      data[0] != H4_EVT)
 329	    {
 330	      return;
 331	    }
 332	
 333	  if (data[1] == BT_HCI_EVT_CMD_COMPLETE && data[2] >= 4)
 334	    {
 335	      opcode = sf32lb52_bt_get_le16(&data[4]);
 336	      if (opcode == BT_HCI_OP_RESET && data[6] != SF32LB52_HCI_STATUS_SUCCESS)
 337	        {
 338	          data[6] = SF32LB52_HCI_STATUS_SUCCESS;
 339	        }
 340	    }
 341	  else if (data[1] == BT_HCI_EVT_CMD_STATUS && data[2] >= 4)
 342	    {
 343	      opcode = sf32lb52_bt_get_le16(&data[5]);
 344	      if (opcode == BT_HCI_OP_RESET && data[3] != SF32LB52_HCI_STATUS_SUCCESS)
 345	        {
 346	          data[3] = SF32LB52_HCI_STATUS_SUCCESS;
 347	        }
