 438	        {
 439	          size_t size;
 440	          size_t read_len;
 441	          int ret;
 442	          struct circular_buf *rx_ring;
 443	          uint32_t wr_ptr;
 444	
 445	          flags = enter_critical_section();
 446	
 447	          if (!env->queue_open || env->ipc_port == IPC_QUEUE_INVALID_HANDLE)
 448	            {
 449	              env->rx_work_pending = false;
 450	              env->rx_worker_running = false;
 451	              leave_critical_section(flags);
 452	              return;
 453	            }
 454	
 455	          leave_critical_section(flags);
 456	
 457	          up_invalidate_dcache((uintptr_t)SF32LB52_BT_RX_BUF_ADDR,
 458	                               (uintptr_t)SF32LB52_BT_RX_BUF_ADDR +
 459	                               SF32LB52_BT_RX_BUF_SIZE);
 460	
 461	          flags = enter_critical_section();
 462	
 463	          if (!env->queue_open || env->ipc_port == IPC_QUEUE_INVALID_HANDLE)
 464	            {
 465	              env->rx_work_pending = false;
 466	              env->rx_worker_running = false;
 467	              leave_critical_section(flags);
 468	              return;
 469	            }
 470	
 471	          rx_ring = (struct circular_buf *)SF32LB52_BT_RX_BUF_ADDR;
 472	          wr_ptr = rx_ring->write_idx_mirror;
 473	          size = sf32lb52_bt_ring_data_len(env->rx_read_idx_mirror,
 474	                                          wr_ptr,
 475	                                          rx_ring->buffer_size);
 476	          if (size == 0)
 477	            {
 478	              uint32_t rd_ptr = rx_ring->read_idx_mirror;
 479	              uint32_t local_rd = env->rx_read_idx_mirror;
 480	
 481	              leave_critical_section(flags);
 482	
 483	              if (empty_retries++ < 20)
 484	                {
 485	                  usleep(1000);
 486	                  continue;
 487	                }
 488	
 489	          #if SF32LB52_BT_TRACE
 490	              syslog(LOG_INFO,
 491	                "sf32lb52 bt rx empty: local=%08lx rd=%08lx wr=%08lx\n",
 492	                (unsigned long)local_rd,
 493	                (unsigned long)rd_ptr,
 494	                (unsigned long)wr_ptr);
 495	          #endif
 496	              break;
 497	            }
 498	
 499	          empty_retries = 0;
 500	
 501	          if (size > sizeof(env->data_buf))
 502	            {
 503	              size = sizeof(env->data_buf);
 504	            }
 505	
 506	          read_len = sf32lb52_bt_ring_copy(env->data_buf, rx_ring,
 507	                                           env->rx_read_idx_mirror, size);
 508	          if (read_len == 0)
 509	            {
 510	              leave_critical_section(flags);
 511	              break;
 512	            }
 513	
 514	          env->rx_read_idx_mirror = sf32lb52_bt_ring_advance(
 515	              env->rx_read_idx_mirror, read_len, rx_ring->buffer_size);
 516	          rx_ring->read_idx_mirror = env->rx_read_idx_mirror;
 517	          __DSB();
 518	
 519	          up_clean_dcache((uintptr_t)SF32LB52_BT_RX_BUF_ADDR,
 520	                          (uintptr_t)SF32LB52_BT_RX_BUF_ADDR +
 521	                          sizeof(*rx_ring));
 522	
 523	          env->rx_count++;
 524	
 525	          leave_critical_section(flags);
 526	
 527	        #if SF32LB52_BT_TRACE
 528	             syslog(LOG_INFO,
 529	               "sf32lb52 bt rx drain: len=%lu local=%08lx wr=%08lx\n",
 530	               (unsigned long)read_len,
 531	               (unsigned long)env->rx_read_idx_mirror,
 532	               (unsigned long)wr_ptr);
 533	        #endif
 534	
 535	          if (env->notify_host == NULL)
 536	            {
 537	              continue;
 538	            }
 539	
 540	          ret = env->notify_host(env->data_buf, read_len);
 541	          if (ret < 0)
 542	            {
 543	              syslog(LOG_ERR,
 544	                     "sf32lb52 bt rx deliver failed: ret=%d len=%u\n",
 545	                     ret, (unsigned int)read_len);
 546	            }
 547	        }
 548	
 549	      flags = enter_critical_section();
 550	      if (!env->rx_work_pending)
 551	        {
 552	          env->rx_worker_running = false;
 553	          leave_critical_section(flags);
 554	          break;
 555	        }
 720	    {
 721	      return ret;
 722	    }
