1078	static uint8_t conn_handle_is_disconnected(struct bt_dev *hdev, uint16_t handle)
1079	{
1080		handle |= ~BT_ACL_HANDLE_MASK;
1081	
1082		for (int i = 0; i < ARRAY_SIZE(hdev->disconnected_handles); i++) {
1083			if (hdev->disconnected_handles[i] == handle) {
1084				hdev->disconnected_handles[i] = 0;
