 351	static int sf32lb52_bt_forward_packet(struct sf32lb52_bt_priv_s *priv,
 352	                                      uint8_t *data, size_t len)
 353	{
 354	  enum bt_buf_type_e type;
 355	  int ret;
 356	
 357	  if (len <= H4_HEADER_SIZE)
 358	    {
 359	      return -EINVAL;
 360	    }
 361	
 362	  switch (data[0])
 363	    {
 364	      case H4_EVT:
 365	        sf32lb52_bt_log_adv_diag_event(data, len);
 366	        #if SF32LB52_BT_NORMALIZE_RESET_STATUS
 367	          sf32lb52_bt_normalize_event(data, len);
 368	        #endif
 369	        type = BT_EVT;
 370	        break;
 371	
 372	      case H4_ACL:
 373	        type = BT_ACL_IN;
 374	        break;
 375	
 376	      case H4_ISO:
 377	        type = BT_ISO_IN;
 378	        break;
 379	
 380	      default:
 381	        return -EINVAL;
 382	    }
 383	
 384	  ret = bt_netdev_receive(&priv->drv,
 385	                          type,
 386	                          (void *)&data[H4_HEADER_SIZE],
 387	                          len - H4_HEADER_SIZE);
 388	  if (ret < 0)
 389	    {
 390	      wlerr("Failed to receive HCI packet: %d\n", ret);
 391	    }
 392	
 393	  return ret;
 394	}
