 396	static int sf32lb52_bt_synth_cmd_complete(struct sf32lb52_bt_priv_s *priv,
 397	                                          uint16_t opcode,
 398	                                          const uint8_t *return_params,
 399	                                          size_t return_len)
 400	{
 401	  uint8_t event[H4_HEADER_SIZE + sizeof(struct bt_hci_evt_hdr_s) + 3 +
 402	                SF32LB52_HCI_MAX_CMD_COMPLETE_RPLEN];
 403	  size_t payload_len;
 404	
 405	  if (return_len > SF32LB52_HCI_MAX_CMD_COMPLETE_RPLEN)
 406	    {
 407	      return -E2BIG;
 408	    }
 409	
 410	  payload_len = 3 + return_len;
 411	  event[0] = H4_EVT;
 412	  event[1] = BT_HCI_EVT_CMD_COMPLETE;
 413	  event[2] = payload_len;
 414	  event[3] = 1;
 415	  sf32lb52_bt_put_le16(&event[4], opcode);
 416	  if (return_len > 0)
 417	    {
 418	      memcpy(&event[6], return_params, return_len);
 419	    }
 420	
 421	  return sf32lb52_bt_forward_packet(priv, event,
 422	                                    H4_HEADER_SIZE +
 423	                                    sizeof(struct bt_hci_evt_hdr_s) +
 424	                                    payload_len);
 425	}
