 553	static int sf32lb52_bt_recv_cb(uint8_t *data, uint16_t len)
 554	{
 555	  struct sf32lb52_bt_priv_s *priv = &g_sf32lb52_bt_priv;
 556	  ssize_t packet_len;
 557	  int ret;
 558	
 559	  if (data == NULL || len == 0)
 560	    {
 561	      return -EINVAL;
 562	    }
 563	
 564	  if (priv->drop_rx_until_tx)
 565	    {
 566	      return OK;
 567	    }
 568	
 569	  if (priv->rxlen + len > sizeof(priv->rxbuf))
 570	    {
 571	      syslog(LOG_ERR,
 572	             "sf32lb52 bth4 rx overflow: pending=%lu incoming=%u\n",
 573	             (unsigned long)priv->rxlen,
 574	             len);
 575	      priv->rxlen = 0;
 576	    }
 577	
 578	  memcpy(&priv->rxbuf[priv->rxlen], data, len);
 579	  priv->rxlen += len;
 580	
 581	#if SF32LB52_BT_TRACE
 582	  if (priv->rxbuf[0] != H4_ACL || SF32LB52_BT_TRACE_ACL)
 583	    {
 584	      syslog(LOG_INFO,
 585	             "sf32lb52 bth4 recv: len=%u pending=%lu first=%02x\n",
 586	             len, (unsigned long)priv->rxlen, priv->rxbuf[0]);
 587	    }
 588	#endif
 589	
 590	  ret = OK;
 591	
 592	  while (priv->rxlen > 0)
 593	    {
 594	      packet_len = sf32lb52_bt_h4_packet_len(priv->rxbuf, priv->rxlen);
 595	      if (packet_len == 0)
 596	        {
 597	          break;
 598	        }
 599	
 600	      if (packet_len < 0)
 601	        {
 602	          syslog(LOG_WARNING,
 603	                 "sf32lb52 bth4 drop invalid h4 type=%02x pending=%lu\n",
 604	                 priv->rxbuf[0],
 605	                 (unsigned long)priv->rxlen);
 606	          memmove(priv->rxbuf, &priv->rxbuf[1], priv->rxlen - 1);
 607	          priv->rxlen--;
 608	          ret = -EINVAL;
 609	          continue;
 610	        }
 611	
 612	      if ((size_t)packet_len > priv->rxlen)
 613	        {
 614	          break;
 615	        }
 616	
 617	      ret = sf32lb52_bt_forward_packet(priv, priv->rxbuf,
 618	                   (size_t)packet_len);
 619	
 620	      priv->rxlen -= (size_t)packet_len;
 621	      if (priv->rxlen > 0)
 622	        {
 623	          memmove(priv->rxbuf,
 624	                  &priv->rxbuf[packet_len],
 625	                  priv->rxlen);
 626	        }
 627	    }
 628	
 629	  return ret;
 630	}
 425	  (void)opcode;
