543	static void *probe_communication_thread(void *arg)
544	{
545	  struct probe_rx_slot_s slot;
546	  bt_address_t peer_addr;
547	  uint32_t generation;
548	  uint32_t active_generation = 0;
549	  uint32_t head;
550	  uint32_t tail;
551	  bool connected;
552	  bool have_slot;
553	  int wait_status;
554	
555	  (void)arg;
556	
557	  for (;;)
558	    {
559	      do
560	        {
561	          wait_status = sem_wait(&g_rx_sem);
562	        }
563	      while (wait_status < 0 && errno == EINTR);
564	
565	      if (wait_status < 0)
566	        {
567	          continue;
568	        }
569	
570	      tail = __atomic_load_n(&g_rx_tail, __ATOMIC_RELAXED);
571	      head = __atomic_load_n(&g_rx_head, __ATOMIC_ACQUIRE);
572	      have_slot = tail != head;
573	      if (have_slot)
574	        {
575	          memcpy(&slot, &g_rx_queue[tail % PROBE_RX_QUEUE_DEPTH],
576	                 sizeof(slot));
577	          __atomic_store_n(&g_rx_tail, tail + 1, __ATOMIC_RELEASE);
578	        }
579	
580	      pthread_mutex_lock(&g_state_lock);
581	      generation = __atomic_load_n(&g_connection_generation,
582	                                   __ATOMIC_ACQUIRE);
583	      connected = g_peer_connected;
584	      memcpy(&peer_addr, &g_peer_addr, sizeof(peer_addr));
585	      pthread_mutex_unlock(&g_state_lock);
586	
587	      if (generation != active_generation)
588	        {
589	          memset(&g_throughput, 0, sizeof(g_throughput));
590	          active_generation = generation;
591	        }
592	
593	      if (!have_slot)
594	        {
595	          continue;
596	        }
597	
598	      if (!connected || slot.connection_generation != generation ||
599	          memcmp(&slot.addr, &peer_addr, sizeof(peer_addr)) != 0)
600	        {
601	          __atomic_fetch_add(&g_rx_stale, 1, __ATOMIC_RELAXED);
602	          continue;
603	        }
604	
605	      probe_process_frame(g_service_handle, slot.value, slot.length);
606	    }
607	
608	  return NULL;
609	}
