394	        }
395	
396	      if (!g_throughput.active)
397	        {
398	          printf("openvela_ble_probe: DATA without active test\n");
399	          return;
400	        }
401	
402	      seq = probe_get_le32(&value[1]);
403	      if (!g_throughput.timing)
404	        {
405	          if (clock_gettime(CLOCK_MONOTONIC,
406	                            &g_throughput.started_at) == 0)
407	            {
408	              g_throughput.timing = true;
409	            }
410	          else
411	            {
412	              printf("openvela_ble_probe: monotonic clock failed\n");
413	            }
414	        }
415	
416	      g_throughput.frames++;
417	      g_throughput.payload_bytes += length - 5;
418	
419	      if (!g_throughput.have_expected_seq)
420	        {
421	          g_throughput.expected_seq = seq + 1;
422	          g_throughput.have_expected_seq = true;
423	        }
424	      else if (seq == g_throughput.expected_seq)
425	        {
426	          g_throughput.expected_seq++;
427	        }
428	      else if (seq > g_throughput.expected_seq)
429	        {
430	          g_throughput.missing_frames += seq - g_throughput.expected_seq;
431	          g_throughput.expected_seq = seq + 1;
432	        }
433	      else
434	        {
435	          g_throughput.missing_frames++;
436	        }
437	
438	      return;
439	    }
440	  else if (length >= 1 && value[0] == 0x12)
441	    {
442	      if (length < 5)
443	        {
444	          printf("openvela_ble_probe: short END length=%u\n", length);
445	          return;
446	        }
447	
448	      id_or_seq = probe_get_le32(&value[1]);
449	      if (!g_throughput.active || id_or_seq != g_throughput.test_id)
450	        {
451	          printf("openvela_ble_probe: unmatched END test_id=%lu\n",
452	                 (unsigned long)id_or_seq);
453	          return;
454	        }
455	
456	      elapsed_ms = g_throughput.timing ?
457	                   probe_elapsed_ms(&g_throughput.started_at) : 0;
458	      response[0] = 0x91;
459	      probe_put_le32(&response[1], g_throughput.test_id);
460	      probe_put_le32(&response[5], g_throughput.frames);
461	      probe_put_le32(&response[9], g_throughput.payload_bytes);
462	      probe_put_le32(&response[13], elapsed_ms);
463	      probe_put_le32(&response[17], g_throughput.missing_frames);
464	
465	      printf("openvela_ble_probe: throughput END test_id=%lu frames=%lu "
466	             "payload=%lu elapsed_ms=%lu missing=%lu\n",
467	             (unsigned long)g_throughput.test_id,
468	             (unsigned long)g_throughput.frames,
469	             (unsigned long)g_throughput.payload_bytes,
470	             (unsigned long)elapsed_ms,
471	             (unsigned long)g_throughput.missing_frames);
472	      status = probe_notify(srv_handle, response, sizeof(response));
473	      printf("openvela_ble_probe: throughput REPORT status=%d\n", status);
474	      probe_print_rx_queue_stats();
475	      memset(&g_throughput, 0, sizeof(g_throughput));
476	      return;
477	    }
478	  else
479	    {
480	      reply = g_error;
481	      reply_len = sizeof(g_error);
482	      printf("openvela_ble_probe: RX unknown command\n");
483	    }
484	
485	  status = probe_notify(srv_handle, reply, reply_len);
486	  printf("openvela_ble_probe: TX notify status=%d\n", status);
487	}
