254	static uint32_t probe_elapsed_ms(const struct timespec *started_at)
255	{
256	  struct timespec ended_at;
257	  int64_t seconds;
258	  int64_t nanoseconds;
259	  uint64_t milliseconds;
260	
261	  if (clock_gettime(CLOCK_MONOTONIC, &ended_at) < 0)
262	    {
263	      return 0;
264	    }
265	
266	  seconds = ended_at.tv_sec - started_at->tv_sec;
267	  nanoseconds = ended_at.tv_nsec - started_at->tv_nsec;
268	  if (nanoseconds < 0)
269	    {
270	      seconds--;
271	      nanoseconds += 1000000000;
272	    }
273	
274	  if (seconds < 0)
275	    {
276	      return 0;
277	    }
278	
279	  milliseconds = (uint64_t)seconds * 1000 +
280	                 (uint64_t)nanoseconds / 1000000;
281	  return milliseconds > UINT32_MAX ? UINT32_MAX : (uint32_t)milliseconds;
282	}
