332	static void probe_process_frame(gatts_handle_t srv_handle,
333	                                const uint8_t *value, uint16_t length)
334	{
335	  uint8_t response[21];
336	  uint8_t *reply;
337	  uint16_t reply_len;
338	  uint32_t elapsed_ms;
339	  uint32_t id_or_seq;
340	  uint32_t seq;
341	  bt_status_t status;
342	
343	  if (length == 4 && memcmp(value, "PING", 4) == 0)
344	    {
345	      reply = g_pong;
346	      reply_len = sizeof(g_pong);
347	      printf("openvela_ble_probe: RX PING\n");
348	    }
349	  else if (length >= 1 && value[0] == 0x01)
350	    {
351	      if (length < 5)
352	        {
353	          printf("openvela_ble_probe: short binary PING length=%u\n",
354	                 length);
355	          return;
356	        }
357	
358	      id_or_seq = probe_get_le32(&value[1]);
359	      response[0] = 0x81;
360	      probe_put_le32(&response[1], id_or_seq);
361	      printf("openvela_ble_probe: RX binary PING seq=%lu\n",
362	             (unsigned long)id_or_seq);
363	      status = probe_notify(srv_handle, response, 5);
364	      printf("openvela_ble_probe: TX binary PONG status=%d\n", status);
365	      return;
366	    }
367	  else if (length >= 1 && value[0] == 0x10)
368	    {
369	      if (length < 5)
370	        {
371	          printf("openvela_ble_probe: short START length=%u\n", length);
372	          return;
373	        }
374	
375	      id_or_seq = probe_get_le32(&value[1]);
376	      memset(&g_throughput, 0, sizeof(g_throughput));
377	      g_throughput.active = true;
378	      g_throughput.test_id = id_or_seq;
379	
380	      response[0] = 0x90;
381	      probe_put_le32(&response[1], id_or_seq);
382	      printf("openvela_ble_probe: throughput START test_id=%lu\n",
383	             (unsigned long)id_or_seq);
384	      status = probe_notify(srv_handle, response, 5);
385	      printf("openvela_ble_probe: throughput START_ACK status=%d\n", status);
386	      return;
387	    }
388	  else if (length >= 1 && value[0] == 0x11)
389	    {
390	      if (length < 5)
391	        {
392	          printf("openvela_ble_probe: short DATA length=%u\n", length);
393	          return;
394	        }
395	
396	      if (!g_throughput.active)
397	        {
398	          printf("openvela_ble_probe: DATA without active test\n");
399	          return;
400	        }
401	
402	      seq = probe_get_le32(&value[1]);
403	      if (!g_throughput.timing)
404	        {
405	          if (clock_gettime(CLOCK_MONOTONIC,
406	                            &g_throughput.started_at) == 0)
407	            {
408	              g_throughput.timing = true;
409	            }
410	          else
411	            {
412	              printf("openvela_ble_probe: monotonic clock failed\n");
413	            }
414	        }
415	
416	      g_throughput.frames++;
417	      g_throughput.payload_bytes += length - 5;
418	
419	      if (!g_throughput.have_expected_seq)
420	        {
