 676	static void *probe_communication_thread(void *arg)
 677	{
 678	  struct probe_rx_slot_s slot;
 679	  bt_address_t peer_addr;
 680	  uint32_t generation;
 681	  uint32_t active_generation = 0;
 682	  uint32_t head;
 683	  uint32_t tail;
 684	  bool connected;
 685	  bool have_slot;
 686	  int wait_status;
 687	
 688	  (void)arg;
 689	
 690	  for (;;)
 691	    {
 692	      do
 693	        {
 694	          wait_status = sem_wait(&g_rx_sem);
 695	        }
 696	      while (wait_status < 0 && errno == EINTR);
 697	
 698	      if (wait_status < 0)
 699	        {
 700	          continue;
 701	        }
 702	
 703	      tail = __atomic_load_n(&g_rx_tail, __ATOMIC_RELAXED);
 704	      head = __atomic_load_n(&g_rx_head, __ATOMIC_ACQUIRE);
 705	      have_slot = tail != head;
 706	      if (have_slot)
 707	        {
 708	          memcpy(&slot, &g_rx_queue[tail % PROBE_RX_QUEUE_DEPTH],
 709	                 sizeof(slot));
 710	          __atomic_store_n(&g_rx_tail, tail + 1, __ATOMIC_RELEASE);
 711	        }
 712	
 713	      pthread_mutex_lock(&g_state_lock);
 714	      generation = __atomic_load_n(&g_connection_generation,
 715	                                   __ATOMIC_ACQUIRE);
 716	      connected = g_peer_connected;
 717	      memcpy(&peer_addr, &g_peer_addr, sizeof(peer_addr));
 718	      pthread_mutex_unlock(&g_state_lock);
 719	
 720	      if (generation != active_generation)
 721	        {
 722	          memset(&g_throughput, 0, sizeof(g_throughput));
 723	          memset(&g_reliable39, 0, sizeof(g_reliable39));
 724	          active_generation = generation;
 725	        }
 726	
 727	      if (!have_slot)
 728	        {
 729	          continue;
 730	        }
 731	
 732	      if (!connected || slot.connection_generation != generation ||
 733	          memcmp(&slot.addr, &peer_addr, sizeof(peer_addr)) != 0)
 734	        {
 735	          __atomic_fetch_add(&g_rx_stale, 1, __ATOMIC_RELAXED);
 736	          continue;
 737	        }
 738	
 739	      probe_process_frame(g_service_handle, slot.value, slot.length,
 740	                          generation);
 741	    }
 742	
 743	  return NULL;
 744	}
