 622	static uint16_t probe_rx_written(gatts_handle_t srv_handle,
 623	                                 bt_address_t *addr,
 624	                                 uint16_t attr_handle,
 625	                                 const uint8_t *value,
 626	                                 uint16_t length,
 627	                                 uint16_t offset)
 628	{
 629	  struct probe_rx_slot_s *slot;
 630	  uint32_t generation;
 631	  uint32_t head;
 632	  uint32_t tail;
 633	  uint32_t used;
 634	
 635	  (void)srv_handle;
 636	  (void)attr_handle;
 637	
 638	  if (offset != 0 || length > PROBE_RX_FRAME_MAX)
 639	    {
 640	      __atomic_fetch_add(&g_rx_invalid_length, 1, __ATOMIC_RELAXED);
 641	      return 0;
 642	    }
 643	
 644	  generation = __atomic_load_n(&g_connection_generation, __ATOMIC_ACQUIRE);
 645	  head = __atomic_load_n(&g_rx_head, __ATOMIC_RELAXED);
 646	  tail = __atomic_load_n(&g_rx_tail, __ATOMIC_ACQUIRE);
 647	  used = head - tail;
 648	  if (used >= PROBE_RX_QUEUE_DEPTH)
 649	    {
 650	      __atomic_fetch_add(&g_rx_drop_full, 1, __ATOMIC_RELAXED);
 651	      return 0;
 652	    }
 653	
 654	  slot = &g_rx_queue[head % PROBE_RX_QUEUE_DEPTH];
 655	  memcpy(&slot->addr, addr, sizeof(slot->addr));
 656	  slot->connection_generation = generation;
 657	  slot->length = length;
 658	  slot->offset = offset;
 659	  memcpy(slot->value, value, length);
 660	  used++;
 661	  if (used >
 662	      __atomic_load_n(&g_rx_high_water, __ATOMIC_RELAXED))
 663	    {
 664	      __atomic_store_n(&g_rx_high_water, used, __ATOMIC_RELAXED);
 665	    }
 666	
 667	  /* Publish only after the complete slot is visible to the consumer. */
 668	
 669	  __atomic_store_n(&g_rx_head, head + 1, __ATOMIC_RELEASE);
 670	
 671	  __atomic_fetch_add(&g_rx_enqueued, 1, __ATOMIC_RELAXED);
 672	  sem_post(&g_rx_sem);
 673	  return length;
 674	}
