{
  bool requested;

  (void)srv_handle;
  (void)addr;

  pthread_mutex_lock(&g_state_lock);
  requested = g_phy_update_requested;
  pthread_mutex_unlock(&g_state_lock);

  printf("openvela_ble_probe: PHY updated status=%d tx=%d rx=%d "
         "requested=%d\n",
         status, tx_phy, rx_phy, requested);
