   217	static int probe_wait_for_ble_startup(uint64_t target_ms)
   218	{
   219	  struct timespec now;
   220	  uint64_t uptime_ms;
   221	  uint64_t remaining_ms;
   222	  uint64_t sleep_ms;
   223	  bool delay_logged = false;
   224	
   225	  for (;;)
   226	    {
   227	      if (clock_gettime(CLOCK_MONOTONIC, &now) < 0)
   228	        {
   229	          printf("openvela_ble_probe: failed to read system uptime\n");
   230	          return -1;
   231	        }
   232	
   233	      uptime_ms = (uint64_t)now.tv_sec * 1000u +
   234	                  (uint64_t)now.tv_nsec / 1000000u;
   235	      if (uptime_ms >= target_ms)
   236	        {
   237	          if (!delay_logged)
   238	            {
   239	              printf("openvela_ble_probe: BLE startup target=%llu ms "
   240	                     "already satisfied\n",
   241	                     (unsigned long long)target_ms);
   242	            }
   243	
   244	          return 0;
   245	        }
   246	
   247	      remaining_ms = target_ms - uptime_ms;
   248	      if (!delay_logged)
   249	        {
   250	          printf("openvela_ble_probe: delaying BLE start %llu ms "
   251	                 "for platform readiness (target=%llu ms)\n",
   252	                 (unsigned long long)remaining_ms,
   253	                 (unsigned long long)target_ms);
   254	          delay_logged = true;
   255	        }
   256	
   257	      sleep_ms = remaining_ms > 100u ? 100u : remaining_ms;
   258	      usleep((useconds_t)(sleep_ms * 1000u));
   259	    }
   260	}
