   551	static void probe_gesture_ack(uint16_t packet_id, uint32_t generation)
   552	{
   553	  struct probe_gesture_record_s *record;
   554	  bool matched = false;
   555	
   556	  pthread_mutex_lock(&g_state_lock);
   557	  if (g_gesture_rx_tail != g_gesture_rx_head)
   558	    {
   559	      record = &g_gesture_queue[g_gesture_rx_tail %
   560	                                PROBE_GESTURE_QUEUE_DEPTH];
   561	      if (record->connection_generation == generation &&
   562	          record->packet_id == packet_id && record->send_count != 0)
   563	        {
   564	          memset(record, 0, sizeof(*record));
   565	          g_gesture_rx_tail++;
   566	          g_gesture_acked++;
   567	          matched = true;
   568	        }
   569	    }
   570	  pthread_mutex_unlock(&g_state_lock);
   571	
   572	  if (matched)
   573	    {
   574	      printf("openvela_ble_probe: gesture ACK packet_id=%u\n", packet_id);
   575	    }
   576	}
