   697	static void probe_process_frame(gatts_handle_t srv_handle,
   698	                                const uint8_t *value, uint16_t length,
   699	                                uint32_t connection_generation)
   700	{
   701	  uint8_t response[21];
   702	  uint8_t *reply;
   703	  uint16_t reply_len;
   704	  uint32_t elapsed_ms;
   705	  uint32_t id_or_seq;
   706	  uint32_t seq;
   707	  bt_status_t status;
   708	
   709	  if (length == 4 && memcmp(value, "PING", 4) == 0)
   710	    {
   711	      reply = g_pong;
   712	      reply_len = sizeof(g_pong);
   713	      printf("openvela_ble_probe: RX PING\n");
   714	    }
   715	  else if (length >= 1 && value[0] == 0x01)
   716	    {
   717	      if (length < 5)
   718	        {
   719	          printf("openvela_ble_probe: short binary PING length=%u\n",
   720	                 length);
   721	          return;
   722	        }
   723	
   724	      id_or_seq = probe_get_le32(&value[1]);
   725	      response[0] = 0x81;
   726	      probe_put_le32(&response[1], id_or_seq);
   727	      printf("openvela_ble_probe: RX binary PING seq=%lu\n",
   728	             (unsigned long)id_or_seq);
   729	      status = probe_notify(srv_handle, response, 5);
   730	      printf("openvela_ble_probe: TX binary PONG status=%d\n", status);
   731	      return;
   732	    }
   733	  else if (length >= 1 && value[0] == PROBE_RELIABLE39_REQUEST_TYPE)
   734	    {
   735	      uint16_t expected_crc;
   736	      uint16_t received_crc;
   737	
   738	      if (length != PROBE_RELIABLE39_FRAME_SIZE)
   739	        {
   740	          __atomic_fetch_add(&g_reliable39_bad_length, 1,
   741	                             __ATOMIC_RELAXED);
   742	          return;
   743	        }
   744	
   745	      received_crc = probe_get_le16(&value[PROBE_RELIABLE39_CRC_OFFSET]);
   746	      expected_crc = probe_crc16_ccitt_false(
   747	        value, PROBE_RELIABLE39_CRC_OFFSET);
   748	      if (received_crc != expected_crc)
   749	        {
   750	          __atomic_fetch_add(&g_reliable39_bad_crc, 1, __ATOMIC_RELAXED);
   751	          return;
   752	        }
   753	
   754	      id_or_seq = probe_get_le32(&value[1]);
   755	      if (g_reliable39.valid &&
   756	          g_reliable39.connection_generation == connection_generation &&
   757	          g_reliable39.sequence == id_or_seq)
   758	        {
   759	          __atomic_fetch_add(&g_reliable39_duplicates, 1,
   760	                             __ATOMIC_RELAXED);
   761	        }
   762	      else
   763	        {
   764	          g_reliable39.response[0] = PROBE_RELIABLE39_RESPONSE_TYPE;
   765	          probe_put_le32(&g_reliable39.response[1], id_or_seq);
   766	          memcpy(&g_reliable39.response[5], &value[5],
   767	                 PROBE_RELIABLE39_PAYLOAD_SIZE);
   768	          probe_put_le16(&g_reliable39.response[PROBE_RELIABLE39_CRC_OFFSET],
   769	                         probe_crc16_ccitt_false(
   770	                           g_reliable39.response,
   771	                           PROBE_RELIABLE39_CRC_OFFSET));
   772	          g_reliable39.connection_generation = connection_generation;
   773	          g_reliable39.sequence = id_or_seq;
   774	          g_reliable39.valid = true;
   775	          __atomic_fetch_add(&g_reliable39_rx_ok, 1, __ATOMIC_RELAXED);
   776	        }
   777	
   778	      __atomic_fetch_add(&g_reliable39_tx_attempted, 1, __ATOMIC_RELAXED);
   779	      status = probe_notify(srv_handle, g_reliable39.response,
   780	                            sizeof(g_reliable39.response));
   781	      if (status != BT_STATUS_SUCCESS)
   782	        {
   783	          __atomic_fetch_add(&g_reliable39_tx_status_nonzero, 1,
   784	                             __ATOMIC_RELAXED);
   785	        }
   786	
   787	      return;
   788	    }
   789	  else if (length >= 1 && value[0] == PROBE_GESTURE_TIME_SYNC_TYPE)
   790	    {
   791	      if (length != 9)
   792	        {
   793	          printf("openvela_ble_probe: invalid gesture time sync length=%u\n",
   794	                 length);
   795	          return;
   796	        }
   797	
   798	      probe_gesture_time_sync(&value[1]);
   799	      return;
   800	    }
   801	  else if (length >= 1 && value[0] == PROBE_GESTURE_ACK_TYPE)
   802	    {
   803	      if (length != 3)
   804	        {
   805	          printf("openvela_ble_probe: invalid gesture ACK length=%u\n",
   806	                 length);
   807	          return;
   808	        }
   809	
   810	      probe_gesture_ack(probe_get_le16(&value[1]),
   811	                        connection_generation);
   812	      return;
   813	    }
   814	  else if (length >= 1 && value[0] == PROBE_GESTURE_INJECT_TYPE)
   815	    {
   816	      if (length != 5)
   817	        {
   818	          printf("openvela_ble_probe: invalid gesture inject length=%u\n",
   819	                 length);
   820	          return;
   821	        }
   822	
   823	#if BLE_PROBE_GESTURE_TEST_INJECT
   824	      status = probe_publish_gesture(value[1], value[2], value[3], value[4]);
   825	      printf("openvela_ble_probe: gesture test inject status=%d\n", status);
   826	#else
   827	      printf("openvela_ble_probe: gesture test inject disabled\n");
   828	#endif
   829	      return;
   830	    }
   831	  else if (length >= 1 && value[0] == 0x10)
   832	    {
   833	      if (length < 5)
   834	        {
   835	          printf("openvela_ble_probe: short START length=%u\n", length);
