   368	static uint32_t probe_elapsed_ms(const struct timespec *started_at)
   369	{
   370	  struct timespec ended_at;
   371	  int64_t seconds;
   372	  int64_t nanoseconds;
   373	  uint64_t milliseconds;
   374	
   375	  if (clock_gettime(CLOCK_MONOTONIC, &ended_at) < 0)
   376	    {
   377	      return 0;
   378	    }
   379	
   380	  seconds = ended_at.tv_sec - started_at->tv_sec;
   381	  nanoseconds = ended_at.tv_nsec - started_at->tv_nsec;
   382	  if (nanoseconds < 0)
   383	    {
   384	      seconds--;
   385	      nanoseconds += 1000000000;
   386	    }
   387	
   388	  if (seconds < 0)
   389	    {
   390	      return 0;
   391	    }
   392	
   393	  milliseconds = (uint64_t)seconds * 1000 +
   394	                 (uint64_t)nanoseconds / 1000000;
   395	  return milliseconds > UINT32_MAX ? UINT32_MAX : (uint32_t)milliseconds;
   396	}
