   232	
   233	      uptime_ms = (uint64_t)now.tv_sec * 1000u +
   234	                  (uint64_t)now.tv_nsec / 1000000u;
   235	      if (uptime_ms >= target_ms)
   236	        {
   237	          if (!delay_logged)
   238	            {
   239	              printf("openvela_ble_probe: BLE startup target=%llu ms "
   240	                     "already satisfied\n",
   241	                     (unsigned long long)target_ms);
   242	            }
   243	
   244	          return 0;
   245	        }
   246	
   247	      remaining_ms = target_ms - uptime_ms;
   248	      if (!delay_logged)
   249	        {
   250	          printf("openvela_ble_probe: delaying BLE start %llu ms "
   251	                 "for platform readiness (target=%llu ms)\n",
   252	                 (unsigned long long)remaining_ms,
   253	                 (unsigned long long)target_ms);
   254	          delay_logged = true;
