   262	static int probe_monotonic_ms(uint64_t *now_ms)
   263	{
   264	  struct timespec now;
   265	
   266	  if (clock_gettime(CLOCK_MONOTONIC, &now) < 0)
   267	    {
   268	      return -1;
   269	    }
   270	
   271	  *now_ms = (uint64_t)now.tv_sec * 1000u +
   272	            (uint64_t)now.tv_nsec / 1000000u;
   273	  return 0;
   274	}
