   276	static uint32_t probe_get_le32(const uint8_t *value)
   277	{
   278	  return (uint32_t)value[0] |
   279	         ((uint32_t)value[1] << 8) |
   280	         ((uint32_t)value[2] << 16) |
   281	         ((uint32_t)value[3] << 24);
   282	}
   283	
   284	static void probe_put_le32(uint8_t *value, uint32_t number)
   285	{
   320	  value[3] = (uint8_t)(number >> 24);
   321	  value[4] = (uint8_t)(number >> 32);
   322	  value[5] = (uint8_t)(number >> 40);
   323	  value[6] = (uint8_t)(number >> 48);
   324	  value[7] = (uint8_t)(number >> 56);
   325	}
   326	
   327	static uint16_t probe_crc16_ccitt_false(const uint8_t *value, size_t length)
   328	{
   329	  uint16_t crc = 0xffff;
   330	  size_t i;
   331	  uint8_t bit;
   332	
   333	  for (i = 0; i < length; i++)
   334	    {
   335	      crc ^= (uint16_t)value[i] << 8;
   336	      for (bit = 0; bit < 8; bit++)
   337	        {
   338	          crc = (crc & 0x8000) != 0 ?
   339	                (uint16_t)((crc << 1) ^ 0x1021) :
   340	                (uint16_t)(crc << 1);
   341	        }
   342	    }
   343	
   344	  return crc;
   345	}
