   464	/* Future gesture producers must use this bounded publisher rather than
   465	 * calling a GATT API.  It is task-context only, never ISR-context.
   466	 */
   467	
   468	static int probe_publish_gesture(uint8_t gesture, uint8_t confidence,
   469	                                 uint8_t flags, uint8_t battery)
   470	{
   471	  struct probe_gesture_record_s *record;
   472	  uint64_t monotonic_ms;
   473	  uint64_t timestamp_ms;
   474	  uint32_t generation;
   475	  uint32_t used;
   476	  bool synced;
   477	
   478	  if (probe_monotonic_ms(&monotonic_ms) < 0)
   479	    {
   480	      return -1;
   481	    }
   482	
   483	  pthread_mutex_lock(&g_state_lock);
   484	  generation = __atomic_load_n(&g_connection_generation, __ATOMIC_ACQUIRE);
   485	  if (!g_peer_connected)
   486	    {
   487	      pthread_mutex_unlock(&g_state_lock);
   488	      return -1;
   489	    }
   490	
   491	  used = g_gesture_rx_head - g_gesture_rx_tail;
   492	  if (used >= PROBE_GESTURE_QUEUE_DEPTH)
   493	    {
   494	      g_gesture_queue_full++;
   495	      pthread_mutex_unlock(&g_state_lock);
   496	      return -1;
   497	    }
   498	
   499	  synced = g_gesture_time_synced;
   500	  timestamp_ms = synced ?
   501	    g_gesture_sync_unix_ms +
   502	      (monotonic_ms - g_gesture_sync_monotonic_ms) : monotonic_ms;
   503	  if (synced)
   504	    {
   505	      flags |= 0x01;
   506	    }
   507	  else
   508	    {
   509	      flags &= (uint8_t)~0x01;
   510	    }
   511	
   512	  record = &g_gesture_queue[g_gesture_rx_head %
   513	                            PROBE_GESTURE_QUEUE_DEPTH];
   514	  memset(record, 0, sizeof(*record));
   515	  record->connection_generation = generation;
   516	  record->packet_id = g_gesture_next_packet_id++;
   517	  record->event[0] = 1;
   518	  record->event[1] = 0x01;
   519	  probe_put_le16(&record->event[2], record->packet_id);
   520	  probe_put_le64(&record->event[4], timestamp_ms);
   521	  record->event[12] = gesture;
   522	  record->event[13] = confidence;
   523	  record->event[14] = flags;
   524	  record->event[15] = battery;
   525	  g_gesture_rx_head++;
   526	  g_gesture_enqueued++;
   527	  pthread_mutex_unlock(&g_state_lock);
   528	
   529	  sem_post(&g_rx_sem);
   530	  return 0;
   531	}
