   533	static void probe_gesture_time_sync(const uint8_t *value)
   534	{
   535	  uint64_t monotonic_ms;
   536	
   537	  if (probe_monotonic_ms(&monotonic_ms) < 0)
   538	    {
   539	      printf("openvela_ble_probe: gesture time sync clock failed\n");
   540	      return;
   541	    }
   542	
   543	  pthread_mutex_lock(&g_state_lock);
   544	  g_gesture_sync_unix_ms = probe_get_le64(value);
   545	  g_gesture_sync_monotonic_ms = monotonic_ms;
   546	  g_gesture_time_synced = true;
   547	  pthread_mutex_unlock(&g_state_lock);
   548	  printf("openvela_ble_probe: gesture time synchronized\n");
   549	}
