   838	
   839	      id_or_seq = probe_get_le32(&value[1]);
   840	      memset(&g_throughput, 0, sizeof(g_throughput));
   841	      g_throughput.active = true;
   842	      g_throughput.test_id = id_or_seq;
   843	
