   953	static uint16_t probe_rx_written(gatts_handle_t srv_handle,
   954	                                 bt_address_t *addr,
   955	                                 uint16_t attr_handle,
   956	                                 const uint8_t *value,
   957	                                 uint16_t length,
   958	                                 uint16_t offset)
   959	{
   960	  struct probe_rx_slot_s *slot;
   961	  uint32_t generation;
   962	  uint32_t head;
   963	  uint32_t tail;
   964	  uint32_t used;
   965	
   966	  (void)srv_handle;
   967	  (void)attr_handle;
   968	
   969	  if (offset != 0 || length > PROBE_RX_FRAME_MAX)
   970	    {
   971	      __atomic_fetch_add(&g_rx_invalid_length, 1, __ATOMIC_RELAXED);
   972	      return 0;
   973	    }
   974	
   975	  generation = __atomic_load_n(&g_connection_generation, __ATOMIC_ACQUIRE);
   976	  head = __atomic_load_n(&g_rx_head, __ATOMIC_RELAXED);
   977	  tail = __atomic_load_n(&g_rx_tail, __ATOMIC_ACQUIRE);
   978	  used = head - tail;
   979	  if (used >= PROBE_RX_QUEUE_DEPTH)
   980	    {
   981	      __atomic_fetch_add(&g_rx_drop_full, 1, __ATOMIC_RELAXED);
   982	      return 0;
   983	    }
   984	
   985	  slot = &g_rx_queue[head % PROBE_RX_QUEUE_DEPTH];
   986	  memcpy(&slot->addr, addr, sizeof(slot->addr));
   987	  slot->connection_generation = generation;
   988	  slot->length = length;
   989	  slot->offset = offset;
   990	  memcpy(slot->value, value, length);
   991	  used++;
   992	  if (used >
   993	      __atomic_load_n(&g_rx_high_water, __ATOMIC_RELAXED))
   994	    {
   995	      __atomic_store_n(&g_rx_high_water, used, __ATOMIC_RELAXED);
   996	    }
   997	
   998	  /* Publish only after the complete slot is visible to the consumer. */
   999	
  1000	  __atomic_store_n(&g_rx_head, head + 1, __ATOMIC_RELEASE);
  1001	
  1002	  __atomic_fetch_add(&g_rx_enqueued, 1, __ATOMIC_RELAXED);
  1003	  sem_post(&g_rx_sem);
  1004	  return length;
  1005	}
