 586	  uint64_t now_ms;
 587	  uint32_t generation;
 588	  uint16_t packet_id = 0;
 589	  uint8_t send_count = 0;
 590	  bool send = false;
 591	  bool dropped = false;
 592	  bt_status_t status;
 593	
 594	  if (probe_monotonic_ms(&now_ms) < 0)
 595	    {
 596	      return;
 597	    }
 598	
 599	  pthread_mutex_lock(&g_state_lock);
 600	  generation = __atomic_load_n(&g_connection_generation, __ATOMIC_ACQUIRE);
 601	  if (g_gesture_rx_tail != g_gesture_rx_head)
 602	    {
 603	      record = &g_gesture_queue[g_gesture_rx_tail %
 604	                                PROBE_GESTURE_QUEUE_DEPTH];
 605	      if (!g_peer_connected || !g_notify_enabled ||
 606	          record->connection_generation != generation)
 607	        {
 608	          if (record->connection_generation != generation)
 609	            {
 610	              g_gesture_rx_tail = g_gesture_rx_head;
 611	            }
 612	        }
 613	      else if (record->send_count == 0 || now_ms >= record->next_retry_ms)
 614	        {
 615	          if (record->send_count >= PROBE_GESTURE_MAX_SENDS)
 616	            {
 617	              packet_id = record->packet_id;
 618	              memset(record, 0, sizeof(*record));
 619	              g_gesture_rx_tail++;
 620	              g_gesture_dropped++;
 621	              dropped = true;
 622	            }
 623	          else
 624	            {
 625	              packet_id = record->packet_id;
 626	              memcpy(event, record->event, sizeof(event));
 627	              record->send_count++;
 628	              send_count = record->send_count;
 629	              record->next_retry_ms =
 630	                now_ms + retry_delays_ms[send_count - 1];
 631	              if (send_count > 1)
 632	                {
 633	                  g_gesture_retransmitted++;
 634	                }
 635	              send = true;
 636	            }
 637	        }
 638	    }
 639	  pthread_mutex_unlock(&g_state_lock);
 640	
