    25	// Initialize all sensors
    26	static void sensors_init(struct rt_sensor_config *cfg)
    27	{
    28	    cfg->intf.dev_name = "i2c3";
    29	    rt_hw_ltr303_init("ltr303", cfg);
    30	    rt_hw_mmc56x3_init("mmc56x3", cfg);
    31	
    32	    cfg->intf.user_data = (void *)LSM6DSL_ADDR_DEFAULT;
    33	    cfg->irq_pin.pin = RT_PIN_NONE;
    34	    rt_hw_lsm6dsl_init("lsm6d", cfg);
    35	}
