    37	// Open and configure sensor devices
    38	static void open_and_config_devices(rt_device_t *ltr303_dev, rt_device_t *mmc56x3_dev,
    39	                                    rt_device_t *lsm6d_dev, rt_device_t *lsm6d_gyro_dev, rt_device_t *lsm6d_step_dev)
    40	{
    41	    *ltr303_dev = rt_device_find("li_ltr303");
    42	    if (*ltr303_dev == RT_NULL)
    43	        rt_kprintf("Can't find device:%s\n", "ltr303");
    44	    else
    45	    {
    46	        rt_err_t ret = rt_device_open(*ltr303_dev, RT_DEVICE_FLAG_RDONLY);
    47	        if (ret != RT_EOK)
    48	            rt_kprintf("open device failed! err: %d\n", ret);
    49	        rt_device_control(*ltr303_dev, RT_SENSOR_CTRL_SET_POWER, (void *)RT_SENSOR_POWER_NORMAL);
    50	    }
    51	
    52	    *mmc56x3_dev = rt_device_find("mag_mmc56x3");
    53	    if (*mmc56x3_dev == RT_NULL)
    54	        rt_kprintf("Can't find device:%s\n", "mmc56x3");
    55	    else
    56	    {
    57	        rt_err_t ret = rt_device_open(*mmc56x3_dev, RT_DEVICE_FLAG_RDONLY);
    58	        if (ret != RT_EOK)
    59	            rt_kprintf("open device failed! err: %d\n", ret);
    60	    }
    61	
    62	    *lsm6d_dev = rt_device_find("acce_lsm");
    63	    *lsm6d_gyro_dev = rt_device_find("gyro_lsm");
    64	    *lsm6d_step_dev = rt_device_find("step_lsm");
    65	    if (*lsm6d_dev == RT_NULL || *lsm6d_gyro_dev == RT_NULL || *lsm6d_step_dev == RT_NULL)
    66	        rt_kprintf("Can't find device:%s\n", "lsm6d");
    67	    else
    68	    {
    69	        rt_err_t ret = rt_device_open(*lsm6d_dev, RT_DEVICE_FLAG_RDONLY);
    70	        ret += rt_device_open(*lsm6d_gyro_dev, RT_DEVICE_FLAG_RDONLY);
    71	        ret += rt_device_open(*lsm6d_step_dev, RT_DEVICE_FLAG_RDONLY);
    72	        if (ret != RT_EOK)
    73	            rt_kprintf("open device failed! err: %d\n", ret);
    74	        rt_device_control(*lsm6d_dev, RT_SENSOR_CTRL_SET_ODR, (void *)1660);
    75	        rt_device_control(*lsm6d_gyro_dev, RT_SENSOR_CTRL_SET_ODR, (void *)1660);
    76	    }
    77	}
