    79	// Sensor data acquisition and printing
    80	static void sensors_loop(rt_device_t ltr303_dev, rt_device_t mmc56x3_dev,
    81	                         rt_device_t lsm6d_dev, rt_device_t lsm6d_gyro_dev, rt_device_t lsm6d_step_dev)
    82	{
    83	    struct rt_sensor_data ltr303, mmc56x3, lsm6d_acce, lsm6d_gyro, lsm6d_step;
    84	    rt_size_t res;
    85	
    86	    res = rt_device_read(ltr303_dev, 0, &ltr303, 1);
    87	    if (res != 1)
    88	        rt_kprintf("read data failed!size is %d\n", res);
    89	    else
    90	        rt_kprintf("light: %d lux\n", ltr303.data.light);
    91	
    92	    res = rt_device_read(mmc56x3_dev, 0, &mmc56x3, 1);
    93	    if (res != 1)
    94	        rt_kprintf("read data failed!size is %d\n", res);
    95	    else
    96	        rt_kprintf("mag, x: %d, y: %d, z: %d\n", mmc56x3.data.mag.x, mmc56x3.data.mag.y, mmc56x3.data.mag.z);
    97	
    98	    res = rt_device_read(lsm6d_dev, 0, &lsm6d_acce, 1);
    99	    if (res != 1)
   100	        rt_kprintf("read data failed!size is %d\n", res);
   101	    else
   102	        rt_kprintf("acce, x: %d, y: %d, z: %d\n", lsm6d_acce.data.acce.x, lsm6d_acce.data.acce.y, lsm6d_acce.data.acce.z);
   103	
   104	    res = rt_device_read(lsm6d_gyro_dev, 0, &lsm6d_gyro, 1);
   105	    if (res != 1)
   106	        rt_kprintf("read data failed!size is %d\n", res);
   107	    else
   108	        rt_kprintf("gyro, x: %d, y: %d, z: %d\n", lsm6d_gyro.data.gyro.x, lsm6d_gyro.data.gyro.y, lsm6d_gyro.data.gyro.z);
   109	
   110	    res = rt_device_read(lsm6d_step_dev, 0, &lsm6d_step, 1);
   111	    if (res != 1)
   112	        rt_kprintf("read data failed!size is %d\n", res);
   113	    else
   114	        rt_kprintf("lsm6d step, step: %d\n", lsm6d_step.data.step);
   115	
   116	    rt_thread_mdelay(100);
   117	    rt_kprintf("\n");
   118	}
