   120	int main(void)
   121	{
   122	    rt_kprintf("Hello world!\n");
   123	
   124	    board_io_init();
   125	
   126	    struct rt_sensor_config cfg;
   127	    sensors_init(&cfg);
   128	
   129	    rt_device_t ltr303_dev, mmc56x3_dev, lsm6d_dev, lsm6d_gyro_dev, lsm6d_step_dev;
   130	    open_and_config_devices(&ltr303_dev, &mmc56x3_dev, &lsm6d_dev, &lsm6d_gyro_dev, &lsm6d_step_dev);
