   372	// Sensor device open and configuration
   373	static void open_and_config_devices(rt_device_t *lsm6d_dev, rt_device_t *lsm6d_gyro_dev, rt_device_t *lsm6d_step_dev)
   374	{
   375	    *lsm6d_dev = rt_device_find(LSM6DSL_LSM6DSL_DEV_NAME);
   376	    if (*lsm6d_dev == RT_NULL)
   377	    {
   378	        rt_kprintf("Can't find accelerometer device: %s\n", LSM6DSL_LSM6DSL_DEV_NAME);
   379	        return;
   380	    }
   381	
   382	    // Open device in read-only mode
   383	    rt_err_t ret = rt_device_open(*lsm6d_dev, RT_DEVICE_FLAG_RDONLY);
   384	    if (ret != RT_EOK)
   385	    {
   386	        rt_kprintf("Open accelerometer device failed! err: %d\n", ret);
   387	        return;
   388	    }
   389	
   390	    // Configure sensor: 52Hz output rate + FIFO mode
   391	    rt_device_control(*lsm6d_dev, RT_SENSOR_CTRL_SET_ODR, (void *)52);
   392	    rt_device_control(*lsm6d_dev, RT_SENSOR_CTRL_SET_MODE, (void *)RT_SENSOR_MODE_FIFO);
   393	    rt_kprintf("Accelerometer device opened: ODR=52Hz, Mode=FIFO\n");
   394	}
