   430	/****************************************************************************
   431	 * Name: lsm6dsl_selftest
   432	 *
   433	 * Description:
   434	 *   Selftesting the sensor.
   435	 *   Mode 0 = selftest accelerometer and mode 1 = selftest gyro
   436	 *
   437	 ****************************************************************************/
   438	
   439	static int lsm6dsl_selftest(FAR struct lsm6dsl_dev_s *priv, uint32_t mode)
   440	{
   900	  lsm6dsl_readreg8(priv, LSM6DSL_TIMESTAMP0_REG, &tstamp0);
   901	  lsm6dsl_readreg8(priv, LSM6DSL_TIMESTAMP1_REG, &tstamp1);
   902	  lsm6dsl_readreg8(priv, LSM6DSL_TIMESTAMP2_REG, &tstamp2);
   903	
   904	  ts = (tstamp2 << 16) | (tstamp1 << 8) | tstamp0;
   905	
   906	  /* Temperature */
   907	
   908	  lsm6dsl_readreg8(priv, LSM6DSL_OUT_TEMP_L, (FAR uint8_t *)&templ);
   909	  lsm6dsl_readreg8(priv, LSM6DSL_OUT_TEMP_H, (FAR uint8_t *)&temph);
   910	
   911	  xf_val = (int16_t) ((hix << 8) | lox);
   912	  yf_val = (int16_t) ((hiy << 8) | loy);
   913	  zf_val = (int16_t) ((hiz << 8) | loz);
   914	
   915	  tempi = (int16_t) ((((int16_t) temph << 8) | (int16_t) templ));
   916	
   917	  temp_val = (tempi / 256) + 25;
   918	
   919	  sninfo("Data 16-bit XL_X--->: %d mg\n",
   920	         (short)(xf_val * g_accelerofactor));
   921	  sninfo("Data 16-bit XL_Y--->: %d mg\n",
   922	         (short)(yf_val * g_accelerofactor));
   923	  sninfo("Data 16-bit XL_Z--->: %d mg\n",
   924	         (short)(zf_val * g_accelerofactor));
   925	  sninfo("Data 16-bit TEMP--->: %d Celsius\n",
   926	         temp_val);
   927	
   928	  sdata->x_data = xf_val * g_accelerofactor;
   929	  sdata->y_data = yf_val * g_accelerofactor;
   930	  sdata->z_data = zf_val * g_accelerofactor;
   931	  sdata->temperature = temp_val;
   932	  sdata->timestamp = ts;
   933	
   934	  x_valg = (int16_t) (((hixg) << 8) | loxg);
   935	  y_valg = (int16_t) (((hiyg) << 8) | loyg);
   936	  z_valg = (int16_t) (((hizg) << 8) | lozg);
   937	
   938	  sninfo("Data 16-bit G_X--->: %d mdps\n", (short)(x_valg * g_gyrofactor));
   939	  sninfo("Data 16-bit G_Y--->: %d mdps\n", (short)(y_valg * g_gyrofactor));
   940	  sninfo("Data 16-bit G_Z--->: %d mdps\n", (short)(z_valg * g_gyrofactor));
   941	
   942	  sdata->g_x_data = x_valg * g_gyrofactor;
   943	  sdata->g_y_data = y_valg * g_gyrofactor;
   944	  sdata->g_z_data = z_valg * g_gyrofactor;
   945	
   946	  return OK;
   947	}
