  1140	/****************************************************************************
  1141	 * Name: lsm6dsl_register
  1142	 *
  1143	 * Description:
  1144	 *   Register the LSM6DSL accelerometer, gyroscope device as 'devpath'.
  1145	 *
  1146	 * Input Parameters:
  1147	 *   devpath - The full path to the driver to register, e.g.
  1148	 *             "/dev/lsm6dsl0", "/dev/gyro0" or "/dev/mag0".
  1149	 *   i2c     - An I2C driver instance.
  1150	 *   addr    - The I2C address of the LSM6DSL accelerometer, gyroscope or
  1151	 *             magnetometer.
  1152	 *   ops     - The device operations structure.
  1153	 *   datareg - The register address of the low byte of the X-coordinate data.
  1154	 *
  1155	 * Returned Value:
  1156	 *   Zero (OK) on success; a negated errno value on failure.
  1157	 *
  1158	 ****************************************************************************/
  1159	
  1160	static int lsm6dsl_register(FAR const char *devpath,
  1161	                            FAR struct i2c_master_s *i2c,
  1162	                            uint8_t addr,
  1163	                            FAR const struct lsm6dsl_ops_s *ops,
  1164	                            uint8_t datareg,
  1165	                            struct lsm6dsl_sensor_data_s sensor_data)
  1166	{
  1167	  FAR struct lsm6dsl_dev_s *priv;
  1168	  int ret;
  1169	
  1170	  /* Sanity check */
  1171	
  1172	  DEBUGASSERT(devpath != NULL);
  1173	  DEBUGASSERT(i2c != NULL);
  1174	  DEBUGASSERT(datareg == LSM6DSL_OUTX_L_XL_SHIFT ||
  1175	              datareg == LSM6DSL_OUTX_L_G_SHIFT);
  1176	
  1177	  /* Initialize the device's structure */
  1178	
  1179	  priv = kmm_malloc(sizeof(*priv));
  1180	  if (priv == NULL)
  1181	    {
  1182	      snerr("ERROR: Failed to allocate instance\n");
  1183	      return -ENOMEM;
  1184	    }
  1185	
  1186	  priv->i2c         = i2c;
  1187	  priv->addr        = addr;
  1188	  priv->ops         = ops;
  1189	  priv->datareg     = datareg;
  1190	  priv->sensor_data = sensor_data;
  1191	
  1192	  /* Configure the device */
  1193	
  1194	  ret = priv->ops->config(priv);
  1195	  if (ret < 0)
  1196	    {
  1197	      snerr("ERROR: Failed to configure device: %d\n", ret);
  1198	      kmm_free(priv);
  1199	      return ret;
  1200	    }
  1201	
  1202	  /* Register the character driver */
  1203	
  1204	  ret = register_driver(devpath, &g_fops, 0666, priv);
  1205	  if (ret < 0)
  1206	    {
  1207	      snerr("ERROR: Failed to register driver: %d\n", ret);
  1208	      kmm_free(priv);
  1209	      return ret;
  1210	    }
  1211	
  1212	  return OK;
  1213	}
