  1099	
  1100	  DEBUGASSERT(priv != NULL);
  1101	
  1102	  /* Handle ioctl commands */
  1103	
  1104	  switch (cmd)
  1105	    {
  1106	      /* Start converting. Arg: None. */
  1107	
  1108	    case SNIOC_START:
  1109	      ret = priv->ops->start(priv);
  1110	      break;
  1111	
  1112	      /* Stop converting. Arg: None. */
  1113	
  1114	    case SNIOC_STOP:
  1115	      ret = priv->ops->stop(priv);
  1116	      break;
  1117	
  1118	    case SNIOC_LSM6DSLSENSORREAD:
  1119	      ret = priv->ops->sensor_read(priv,
  1120	                                   (FAR struct lsm6dsl_sensor_data_s *) arg);
  1121	      break;
  1122	
  1123	    case SNIOC_START_SELFTEST:
  1124	      ret = priv->ops->selftest(priv, (uint32_t) arg);
  1125	      break;
  1126	
  1127	      /* Unrecognized commands */
  1128	
  1129	    default:
  1130	      {
  1131	        snerr("ERROR: Unrecognized cmd: %d arg: %lu\n", cmd, arg);
  1132	        ret = -ENOTTY;
  1133	      }
  1134	      break;
  1135	    }
  1136	
  1137	  return ret;
  1138	}
