  1157	 *
  1158	 ****************************************************************************/
  1159	
  1160	static int lsm6dsl_register(FAR const char *devpath,
  1161	                            FAR struct i2c_master_s *i2c,
  1162	                            uint8_t addr,
  1163	                            FAR const struct lsm6dsl_ops_s *ops,
  1164	                            uint8_t datareg,
  1165	                            struct lsm6dsl_sensor_data_s sensor_data)
  1166	{
