   306	 *
   307	 ****************************************************************************/
   308	
   309	static int lsm6dsl_sensor_config(FAR struct lsm6dsl_dev_s *priv)
   310	{
   311	  int ret;
   312	  uint8_t regval;
   313	
   314	  /* Sanity check */
   315	
   316	  DEBUGASSERT(priv != NULL);
   317	
   318	  /* Get the device identification */
   319	
   320	  ret = lsm6dsl_readreg8(priv, LSM6DSL_WHO_AM_I, &regval);
   321	  if (ret < 0)
   322	    {
   323	      snerr("ERROR: lsm6dsl_readreg8 failed: %d\n", ret);
   324	      return ret;
   325	    }
   326	
   327	  if (regval != LSM6DSL_WHO_AM_I_VALUE)
   328	    {
   329	      snerr("ERROR: Invalid device identification %02x\n", regval);
   330	      return -ENODEV;
   331	    }
   332	
   333	  return OK;
   334	}
