   354	/****************************************************************************
   355	 * Name: lsm6dsl_sensor_start
   356	 *
   357	 * Description:
   358	 *   Start the accelerometer.
   359	 *
   360	 ****************************************************************************/
   361	
   362	static int lsm6dsl_sensor_start(FAR struct lsm6dsl_dev_s *priv)
   363	{
   364	  /* Enable the accelerometer */
   365	
   366	  /* Reset values */
   367	
   368	  lsm6dsl_resetsensor(priv);
   369	
   370	  /* Sanity check */
   371	
   372	  DEBUGASSERT(priv != NULL);
   373	
   374	  sninfo("Starting....");
   375	
   376	  /* Accelerometer config registers:
   377	   * Turn on the accelerometer: 833Hz, +- 16g
   378	   */
   379	
   380	  lsm6dsl_writereg8(priv, LSM6DSL_CTRL1_XL, 0x74);
   381	  g_accelerofactor = 0.488;
   382	
   383	  /* Gyro config registers Turn on the gyro: FS=2000dps, ODR=833Hz Not using
   384	   * modifyreg with empty value!!!! Then read value first!!!
   385	   */
   386	
   387	  lsm6dsl_writereg8(priv, LSM6DSL_CTRL2_G, 0x7c);
   388	  g_gyrofactor = 70;
   389	
   390	  lsm6dsl_writereg8(priv, LSM6DSL_CTRL6_C, 0x00);
   391	
   392	  /* Timestamp registers */
   393	
   394	  lsm6dsl_writereg8(priv, LSM6DSL_CTRL10_C, 0x20);
   395	
   396	  return OK;
   397	}
