   949	/****************************************************************************
   950	 * Name: lsm6dsl_read
   951	 *
   952	 * Description:
   953	 *   The standard read method.
   954	 *
   955	 ****************************************************************************/
   956	
   957	static ssize_t lsm6dsl_read(FAR struct file *filep,
   958	                            FAR char *buffer, size_t buflen)
   959	{
   960	  FAR struct inode *inode;
   961	  FAR struct lsm6dsl_dev_s *priv;
   962	  int ret;
   963	  size_t i;
   964	  size_t j;
   965	  size_t samplesize;
   966	  size_t nsamples;
   967	  uint16_t data;
   968	  FAR int16_t *ptr;
   969	  uint8_t regaddr;
   970	  uint8_t lo;
   971	  uint8_t hi;
   972	  uint32_t merge = 0;
   973	
   974	  /* Sanity check */
   975	
   976	  inode = filep->f_inode;
   977	
   978	  priv = inode->i_private;
   979	
   980	  DEBUGASSERT(priv != NULL);
   981	  DEBUGASSERT(priv->datareg == LSM6DSL_OUTX_L_G_SHIFT ||
   982	              priv->datareg == LSM6DSL_OUTX_L_XL_SHIFT);
   983	  DEBUGASSERT(buffer != NULL);
   984	
   985	  samplesize = 3 * sizeof(*ptr);
   986	  nsamples = buflen / samplesize;
   987	  ptr = (FAR int16_t *) buffer;
   988	
   989	  /* Get the requested number of samples */
   990	
   991	  for (i = 0; i < nsamples; i++)
   992	    {
   993	      /* Reset the register address to the X low byte register */
   994	
   995	      regaddr = priv->datareg;
   996	
   997	      /* Read the X, Y and Z data */
   998	
   999	      for (j = 0; j < 3; j++)
  1000	        {
  1001	          /* Read the low byte */
  1002	
  1003	          ret = lsm6dsl_readreg8(priv, regaddr, &lo);
  1004	          if (ret < 0)
  1005	            {
  1006	              snerr("ERROR: lsm6dsl_readreg8 failed: %d\n", ret);
  1007	              return (ssize_t) ret;
  1008	            }
  1009	
  1010	          regaddr++;
  1011	
  1012	          /* Read the high byte */
  1013	
  1014	          ret = lsm6dsl_readreg8(priv, regaddr, &hi);
  1015	          if (ret < 0)
  1016	            {
  1017	              snerr("ERROR: lsm6dsl_readreg8 failed: %d\n", ret);
  1018	              return (ssize_t) ret;
  1019	            }
  1020	
  1021	          regaddr++;
  1022	
  1023	          /* The data is 16 bits in two's complement representation */
  1024	
  1025	          data = ((uint16_t) hi << 8) | (uint16_t) lo;
  1026	
  1027	          /* Collect entropy */
  1028	
  1029	          merge += data ^ (merge >> 16);
  1030	
  1031	          /* The value is positive */
  1032	
  1033	          if (data < 0x8000)
  1034	            {
  1035	              ptr[j] = (int16_t) data;
  1036	            }
  1037	
  1038	          /* The value is negative, so find its absolute value by taking the
  1039	           * two's complement
  1040	           */
  1080	/****************************************************************************
  1081	 * Name: lsm6dsl_ioctl
  1082	 *
  1083	 * Description:
  1084	 *   The standard ioctl method.
  1085	 *
  1086	 ****************************************************************************/
  1087	
  1088	static int lsm6dsl_ioctl(FAR struct file *filep, int cmd, unsigned long arg)
  1089	{
  1090	  FAR struct inode *inode;
  1091	  FAR struct lsm6dsl_dev_s *priv;
  1092	  int ret;
  1093	
  1094	  /* Sanity check */
  1095	
  1096	  inode = filep->f_inode;
  1097	
  1098	  priv = inode->i_private;
  1099	
  1100	  DEBUGASSERT(priv != NULL);
  1101	
  1102	  /* Handle ioctl commands */
  1103	
  1104	  switch (cmd)
  1105	    {
  1106	      /* Start converting. Arg: None. */
  1107	
  1108	    case SNIOC_START:
  1109	      ret = priv->ops->start(priv);
  1110	      break;
  1111	
  1112	      /* Stop converting. Arg: None. */
  1113	
  1114	    case SNIOC_STOP:
  1115	      ret = priv->ops->stop(priv);
  1116	      break;
  1117	
  1118	    case SNIOC_LSM6DSLSENSORREAD:
  1119	      ret = priv->ops->sensor_read(priv,
  1120	                                   (FAR struct lsm6dsl_sensor_data_s *) arg);
  1121	      break;
  1122	
  1123	    case SNIOC_START_SELFTEST:
  1124	      ret = priv->ops->selftest(priv, (uint32_t) arg);
  1125	      break;
  1126	
  1127	      /* Unrecognized commands */
  1128	
  1129	    default:
  1130	      {
  1131	        snerr("ERROR: Unrecognized cmd: %d arg: %lu\n", cmd, arg);
  1132	        ret = -ENOTTY;
  1133	      }
  1134	      break;
  1135	    }
  1136	
  1137	  return ret;
  1138	}
