 95	            HAL_Delay_us(80);
 96	
 97	  /* Keep divider aligned with existing board implementation. */
 98	
 99	  g_psram_ready = (HAL_MPI_PSRAM_Init(&psram_handle, &qspi_cfg, 2) == HAL_OK);
100	}
101	#endif
